"""Small YAML reader/writer for the common data-only YAML subset."""
import json
import re


def _scalar(s):
    s = s.strip()
    if not s:
        return None
    if s in ('null', 'Null', 'NULL', '~'):
        return None
    if s.lower() == 'true': return True
    if s.lower() == 'false': return False
    if s.startswith(('"', "'")):
        try:
            if s[0] == '"': return json.loads(s)
            if s.endswith("'"): return s[1:-1].replace("''", "'")
        except Exception: pass
    if s.startswith('[') or s.startswith('{'):
        try: return json.loads(s)
        except Exception:
            if s.startswith('[') and s.endswith(']'):
                return [_scalar(x) for x in _split_inline(s[1:-1]) if x.strip()]
    if re.fullmatch(r'[-+]?(?:0|[1-9][0-9]*)(?:_[0-9]+)*', s):
        try: return int(s.replace('_',''))
        except ValueError: pass
    if re.fullmatch(r'[-+]?(?:[0-9]+\.[0-9]*|\.[0-9]+)(?:[eE][-+]?[0-9]+)?', s):
        try: return float(s)
        except ValueError: pass
    return s


def _split_inline(s):
    out=[]; start=0; quote=None; depth=0
    for i,c in enumerate(s):
        if quote:
            if c == quote: quote=None
        elif c in "'\"": quote=c
        elif c in '[{(': depth+=1
        elif c in ']})': depth-=1
