        pad=" "*depth
        if isinstance(val, dict):
            if not val: return [f"{pad}<{key}></{key}>"]
            lines=[f"{pad}<{key}>"]
            for k,v in val.items(): lines.extend(field(k,v,depth+2))
            lines.append(f"{pad}</{key}>")
            return lines
        if isinstance(val, list):
            if not val: return []
            if depth == 0:
                lines=[f"{pad}<{key}>"]
                for item in val:
                    if isinstance(item,dict):
                        for k,v in item.items(): lines.extend(field(k,v,depth+2))
                    else: lines.extend(field(key,item,depth+2))
                lines.append(f"{pad}</{key}>")
                return lines
            lines=[]
            for item in val:
                if isinstance(item,dict):
                    lines.append(f"{pad}<{key}>")
                    for k,v in item.items(): lines.extend(field(k,v,depth+2))
                    lines.append(f"{pad}</{key}>")
                else: lines.extend(field(key,item,depth))
            return lines
        return [f"{pad}<{key}>{scalar(val)}</{key}>"]
    if isinstance(value,dict):
        blocks=[]
        for k,v in value.items(): blocks.append("\n".join(field(k,v,0)))
        return "\n\n".join(blocks)+"\n"
    return scalar(value)+"\n"

"""Helpers for Dasel recursive descent and search selectors.

These operate on ordinary Python JSON-like values and are kept separate from
the query parser so the CLI implementation can use them directly.
"""

def _children(value):
    if isinstance(value, dict):
        return value.values()
    if isinstance(value, list):
        return value
    return ()


def recursive_values(root, key):
    """Return values at key in descendant objects, in depth-first order.

    The root object's own keys are not considered by the reference `..key`
    selector; its children are searched.
    """
    out = []
    def walk(value):
        if isinstance(value, dict):
            for k, v in value.items():
                if k == key:
                    out.append(v)
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    for child in _children(root):
        walk(child)
    return out


